      setProgress((current) => {
        if (current >= 92) {
          complete();
          return 100;
        }
        return current + 12;
      });
    }, 40);

    const fallback = window.setTimeout(complete, 450);

    return () => {
      if (timer) window.clearInterval(timer);
      window.clearTimeout(fallback);
    };
  }, [reduceMotion]);

  if (!visible) return null;"

